"""Lexer and recursive-descent parser: SQL text to an ast.Select. See SPEC.md."""

from typing import List, NamedTuple, Optional, Union

from .ast import (
    Between,
    Binary,
    Column,
    FuncCall,
    InList,
    IsNull,
    Like,
    Literal,
    OrderItem,
    Select,
    SelectItem,
    Unary,
)
from .errors import QueryError

KEYWORDS = frozenset(
    """SELECT DISTINCT FROM WHERE GROUP BY HAVING ORDER ASC DESC LIMIT OFFSET
    AS AND OR NOT IS NULL IN BETWEEN LIKE TRUE FALSE""".split()
)

# Longest first, so "<=" wins over "<".
OPERATORS = ("<=", ">=", "<>", "!=", "||", "=", "<", ">", "+", "-", "*", "/", "(", ")", ",", ";")

COMPARISONS = ("=", "!=", "<>", "<", "<=", ">", ">=")


class Token(NamedTuple):
    # kind: "num", "str", "name" (unquoted), "qname" (quoted), "kw", "op", "eof".
    # value: the number, the unescaped text, the uppercased keyword, or the operator.
    kind: str
    value: Union[int, float, str, None]
    start: int
    end: int


def _is_digit(c: str) -> bool:
    return "0" <= c <= "9"


def _is_name_start(c: str) -> bool:
    return c == "_" or "a" <= c <= "z" or "A" <= c <= "Z"


def _is_name_char(c: str) -> bool:
    return _is_name_start(c) or _is_digit(c)


def _describe(tok: Token, sql: str) -> str:
    if tok.kind == "eof":
        return "end of query"
    return repr(sql[tok.start : tok.end])


def tokenize(sql: str) -> List[Token]:
    """Split ``sql`` into tokens, ending with an "eof" token."""
    tokens = []
    i, n = 0, len(sql)
    while i < n:
        c = sql[i]
        if c.isspace():
            i += 1
        elif _is_digit(c) or (c == "." and i + 1 < n and _is_digit(sql[i + 1])):
            start = i
            while i < n and _is_digit(sql[i]):
                i += 1
            is_float = i < n and sql[i] == "."
            if is_float:
                i += 1
                while i < n and _is_digit(sql[i]):
                    i += 1
            # Reject things like "12abc" or "1.2.3" rather than splitting them.
            if i < n and (_is_name_char(sql[i]) or sql[i] == "."):
                raise QueryError("invalid number at position %d: %r" % (start, sql[start : i + 1]))
            text = sql[start:i]
            tokens.append(Token("num", float(text) if is_float else int(text), start, i))
        elif _is_name_start(c):
            start = i
            while i < n and _is_name_char(sql[i]):
                i += 1
            word = sql[start:i]
            if word.upper() in KEYWORDS:
                tokens.append(Token("kw", word.upper(), start, i))
            else:
                tokens.append(Token("name", word, start, i))
        elif c in "'\"":
            # String literal or quoted name; a doubled quote is an escaped quote.
            start = i
            i += 1
            parts = []
            while True:
                j = sql.find(c, i)
                if j < 0:
                    what = "string" if c == "'" else "quoted name"
                    raise QueryError("unterminated %s starting at position %d" % (what, start))
                parts.append(sql[i:j])
                if j + 1 < n and sql[j + 1] == c:
                    parts.append(c)
                    i = j + 2
                else:
                    i = j + 1
                    break
            tokens.append(Token("str" if c == "'" else "qname", "".join(parts), start, i))
        else:
            for op in OPERATORS:
                if sql.startswith(op, i):
                    tokens.append(Token("op", op, i, i + len(op)))
                    i += len(op)
                    break
            else:
                raise QueryError("unexpected character %r at position %d" % (c, i))
    tokens.append(Token("eof", None, n, n))
    return tokens


class _Parser:
    def __init__(self, sql: str):
        self.sql = sql
        self.tokens = tokenize(sql)
        self.pos = 0

    # -- token helpers --

    @property
    def tok(self) -> Token:
        return self.tokens[self.pos]

    def advance(self) -> Token:
        tok = self.tokens[self.pos]
        if tok.kind != "eof":
            self.pos += 1
        return tok

    def at(self, kind: str, *values) -> bool:
        tok = self.tok
        return tok.kind == kind and (not values or tok.value in values)

    def at_kw(self, *words) -> bool:
        return self.at("kw", *words)

    def at_op(self, *ops) -> bool:
        return self.at("op", *ops)

    def accept_kw(self, word: str) -> bool:
        if self.at_kw(word):
            self.advance()
            return True
        return False

    def accept_op(self, op: str) -> bool:
        if self.at_op(op):
            self.advance()
            return True
        return False

    def error(self, expected: str) -> QueryError:
        tok = self.tok
        return QueryError(
            "syntax error at position %d: expected %s, got %s"
            % (tok.start, expected, _describe(tok, self.sql))
        )

    def expect_kw(self, word: str) -> None:
        if not self.accept_kw(word):
            raise self.error(word)

    def expect_op(self, op: str) -> None:
        if not self.accept_op(op):
            raise self.error(repr(op))

    def name(self, what: str) -> str:
        if self.at("name") or self.at("qname"):
            return self.advance().value
        raise self.error(what)

    def integer(self, what: str) -> int:
        tok = self.tok
        if tok.kind == "num" and isinstance(tok.value, int):
            self.advance()
            return tok.value
        raise self.error("a non-negative integer after " + what)

    # -- query --

    def query(self) -> Select:
        if self.at("eof"):
            raise QueryError("empty query")
        self.expect_kw("SELECT")
        distinct = self.accept_kw("DISTINCT")
        if self.accept_op("*"):
            columns = None
        else:
            items = [self.select_item()]
            while self.accept_op(","):
                items.append(self.select_item())
            columns = tuple(items)
        self.expect_kw("FROM")
        table = self.name("a table name")

        where = self.expr() if self.accept_kw("WHERE") else None

        group_by = ()
        if self.accept_kw("GROUP"):
            self.expect_kw("BY")
            exprs = [self.expr()]
            while self.accept_op(","):
                exprs.append(self.expr())
            group_by = tuple(exprs)

        having = self.expr() if self.accept_kw("HAVING") else None

        order_by = ()
        if self.accept_kw("ORDER"):
            self.expect_kw("BY")
            items = [self.order_item()]
            while self.accept_op(","):
                items.append(self.order_item())
            order_by = tuple(items)

        limit = offset = None
        if self.accept_kw("LIMIT"):
            limit = self.integer("LIMIT")
            if self.accept_kw("OFFSET"):
                offset = self.integer("OFFSET")

        self.accept_op(";")
        if not self.at("eof"):
            raise self.error("end of query")
        return Select(distinct, columns, table, where, group_by, having, order_by, limit, offset)

    def select_item(self) -> SelectItem:
        start = self.tok.start
        expr = self.expr()
        text = self.sql[start : self.tokens[self.pos - 1].end]
        alias = None
        if self.accept_kw("AS"):
            alias = self.name("an alias after AS")
        elif self.at("name") or self.at("qname"):
            alias = self.advance().value
        return SelectItem(expr, alias, text)

    def order_item(self) -> OrderItem:
        expr = self.expr()
        if self.accept_kw("DESC"):
            return OrderItem(expr, True)
        self.accept_kw("ASC")
        return OrderItem(expr, False)

    # -- expressions, lowest precedence first --

    def expr(self):
        return self.or_expr()

    def or_expr(self):
        left = self.and_expr()
        while self.accept_kw("OR"):
            left = Binary("OR", left, self.and_expr())
        return left

    def and_expr(self):
        left = self.not_expr()
        while self.accept_kw("AND"):
            left = Binary("AND", left, self.not_expr())
        return left

    def not_expr(self):
        if self.accept_kw("NOT"):
            return Unary("NOT", self.not_expr())
        return self.comparison()

    def comparison(self):
        left = self.additive()
        result = self.comparison_tail(left)
        if result is not left and self.at_comparison():
            raise QueryError(
                "syntax error at position %d: comparisons can't be chained; use parentheses"
                % self.tok.start
            )
        return result

    def at_comparison(self) -> bool:
        return self.at_op(*COMPARISONS) or self.at_kw("IS", "IN", "BETWEEN", "LIKE") or (
            self.at_kw("NOT") and self.tokens[self.pos + 1].kind == "kw"
            and self.tokens[self.pos + 1].value in ("IN", "BETWEEN", "LIKE")
        )

    def comparison_tail(self, left):
        """Parse at most one comparison operator applied to ``left``."""
        if self.at_op(*COMPARISONS):
            op = self.advance().value
            return Binary("!=" if op == "<>" else op, left, self.additive())
        if self.accept_kw("IS"):
            negated = self.accept_kw("NOT")
            self.expect_kw("NULL")
            return IsNull(left, negated)
        if self.at_kw("NOT"):
            nxt = self.tokens[self.pos + 1]
            if not (nxt.kind == "kw" and nxt.value in ("IN", "BETWEEN", "LIKE")):
                raise QueryError(
                    "syntax error at position %d: expected IN, BETWEEN or LIKE after NOT, got %s"
                    % (nxt.start, _describe(nxt, self.sql))
                )
            self.advance()
            negated = True
        elif self.at_kw("IN", "BETWEEN", "LIKE"):
            negated = False
        else:
            return left
        word = self.advance().value
        if word == "IN":
            self.expect_op("(")
            items = [self.expr()]
            while self.accept_op(","):
                items.append(self.expr())
            self.expect_op(")")
            return InList(left, tuple(items), negated)
        if word == "BETWEEN":
            low = self.additive()
            self.expect_kw("AND")
            return Between(left, low, self.additive(), negated)
        return Like(left, self.additive(), negated)

    def additive(self):
        left = self.multiplicative()
        while self.at_op("+", "-", "||"):
            op = self.advance().value
            left = Binary(op, left, self.multiplicative())
        return left

    def multiplicative(self):
        left = self.unary()
        while self.at_op("*", "/"):
            op = self.advance().value
            left = Binary(op, left, self.unary())
        return left

    def unary(self):
        if self.accept_op("-"):
            return Unary("-", self.unary())
        return self.primary()

    def primary(self):
        tok = self.tok
        if tok.kind in ("num", "str"):
            self.advance()
            return Literal(tok.value)
        if tok.kind == "kw" and tok.value in ("NULL", "TRUE", "FALSE"):
            self.advance()
            return Literal({"NULL": None, "TRUE": True, "FALSE": False}[tok.value])
        if tok.kind == "qname":
            self.advance()
            return Column(tok.value)
        if tok.kind == "name":
            self.advance()
            if self.accept_op("("):
                return self.call(tok.value.upper())
            return Column(tok.value)
        if self.accept_op("("):
            inner = self.expr()
            self.expect_op(")")
            return inner
        if tok.kind == "kw":
            raise QueryError(
                "syntax error at position %d: expected an expression, got keyword %s"
                " (quote it to use it as a name)" % (tok.start, tok.value)
            )
        raise self.error("an expression")

    def call(self, name: str) -> FuncCall:
        """Parse a call's arguments; the opening "(" is already consumed."""
        if self.at_op("*"):
            if name != "COUNT":
                raise QueryError(
                    "syntax error at position %d: only COUNT accepts *, not %s"
                    % (self.tok.start, name)
                )
            self.advance()
            self.expect_op(")")
            return FuncCall(name, (), star=True)
        args = []
        if not self.at_op(")"):
            args.append(self.expr())
            while self.accept_op(","):
                args.append(self.expr())
        self.expect_op(")")
        return FuncCall(name, tuple(args))


def parse(sql: str) -> Select:
    """Parse one SELECT query, raising QueryError on any syntax error."""
    if not isinstance(sql, str):
        raise QueryError("query must be a string")
    return _Parser(sql).query()

"""Execute a parsed query against a directory of CSV files. See SPEC.md.

Expressions are compiled once into Python closures, which checks columns,
functions, argument counts and grouping rules before any row is read, so
those errors don't depend on the data. A compiled expression is a function
of a context: a row tuple in an ungrouped query, or a _Group in a grouped
one.

Values are None (NULL), bool, int, float and str. Since bool is a subclass
of int in Python, type checks below always test for bool first.
"""

import csv
import math
import operator
import os
import re
from dataclasses import dataclass, fields
from decimal import ROUND_HALF_UP, Context, Decimal
from functools import lru_cache
from typing import Callable, List, Optional, Tuple

from .ast import (
    Between,
    Binary,
    Column,
    Expr,
    FuncCall,
    InList,
    IsNull,
    Like,
    Literal,
    Select,
    Unary,
)
from .errors import QueryError

_NODES = (Literal, Column, Unary, Binary, IsNull, InList, Between, Like, FuncCall)


@dataclass
class Result:
    columns: List[str]
    rows: List[tuple]


def execute(select: Select, directory: str) -> Result:
    """Run ``select`` against the CSV files in ``directory``."""
    return _Query(select, _load_table(directory, select.table)).run()


# Tables

_INTEGER = re.compile(r"-?[0-9]+")
_DECIMAL = re.compile(r"-?[0-9]+\.[0-9]*|-?[0-9]*\.[0-9]+")


@dataclass
class _Table:
    name: str
    header: List[str]
    rows: List[tuple]

    def column_index(self, name: str) -> int:
        matches = [i for i, h in enumerate(self.header) if h.lower() == name.lower()]
        if not matches:
            raise QueryError(f"unknown column: {name}")
        if len(matches) > 1:
            raise QueryError(f"ambiguous column: {name}")
        return matches[0]


def _convert(field: str):
    if field == "":
        return None
    if _INTEGER.fullmatch(field):
        return int(field)
    if _DECIMAL.fullmatch(field):
        return float(field)
    return field


def _load_table(directory: str, name: str) -> _Table:
    """Read ``name.csv``. Blank lines are skipped; ragged rows are errors."""
    separators = {"/", "\\", os.sep, os.altsep, "\0"} - {None}
    if not name or any(sep in name for sep in separators):
        raise QueryError(f"invalid table name: {name!r}")
    path = os.path.join(directory, name + ".csv")
    try:
        with open(path, newline="", encoding="utf-8-sig") as f:
            reader = csv.reader(f)
            header = None
            rows = []
            for record in reader:
                if not record:
                    continue
                if header is None:
                    header = record
                elif len(record) != len(header):
                    raise QueryError(
                        f"table {name}: line {reader.line_num} has {len(record)} "
                        f"fields, expected {len(header)}"
                    )
                else:
                    rows.append(tuple(_convert(field) for field in record))
    except FileNotFoundError:
        raise QueryError(f"unknown table: {name}") from None
    except (OSError, UnicodeDecodeError, csv.Error) as e:
        raise QueryError(f"cannot read table {name}: {e}") from None
    if header is None:
        raise QueryError(f"table {name} has no header")
    return _Table(name, header, rows)


# Values

def _kind(value) -> str:
    if isinstance(value, bool):
        return "boolean"
    if isinstance(value, (int, float)):
        return "number"
    return "string"


def _is_number(value) -> bool:
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _require(kind: str, what: str, *values) -> None:
    """Check that every non-NULL value is of ``kind``."""
    for value in values:
        if value is not None and _kind(value) != kind:
            raise QueryError(f"{what} expects a {kind}, got {_kind(value)} {value!r}")


def _value_key(value):
    """A hashable key under which only equal values of the same kind match."""
    return (isinstance(value, bool), value)


def _text(value) -> str:
    if isinstance(value, bool):
        return "true" if value else "false"
    return str(value)


def _compare(a, b) -> int:
    """Compare two non-NULL values: -1, 0 or 1."""
    if _kind(a) != _kind(b):
        raise QueryError(f"cannot compare {_kind(a)} {a!r} with {_kind(b)} {b!r}")
    return (a > b) - (a < b)


# Operators

def _comparison(symbol: str, test: Callable[[int], bool]):
    def op(a, b):
        if a is None or b is None:
            return None
        return test(_compare(a, b))
    return op


def _arithmetic(symbol: str, fn):
    def op(a, b):
        _require("number", symbol, a, b)
        if a is None or b is None:
            return None
        try:
            result = fn(a, b)
        except OverflowError:
            raise QueryError(f"numeric overflow in {symbol}") from None
        return result if isinstance(a, int) and isinstance(b, int) else float(result)
    return op


def _divide(a, b):
    _require("number", "/", a, b)
    if a is None or b is None or b == 0:
        return None
    try:
        return a / b
    except OverflowError:
        raise QueryError("numeric overflow in /") from None


def _concat(a, b):
    if a is None or b is None:
        return None
    return _text(a) + _text(b)


def _and(a, b):
    _require("boolean", "AND", a, b)
    if a is False or b is False:
        return False
    if a is None or b is None:
        return None
    return True


def _or(a, b):
    _require("boolean", "OR", a, b)
    if a is True or b is True:
        return True
    if a is None or b is None:
        return None
    return False


def _not(a):
    _require("boolean", "NOT", a)
    return None if a is None else not a


def _negate(a):
    _require("number", "unary -", a)
    return None if a is None else -a


_BINARY = {
    "OR": _or,
    "AND": _and,
    "=": _comparison("=", lambda c: c == 0),
    "!=": _comparison("!=", lambda c: c != 0),
    "<>": _comparison("<>", lambda c: c != 0),
    "<": _comparison("<", lambda c: c < 0),
    "<=": _comparison("<=", lambda c: c <= 0),
    ">": _comparison(">", lambda c: c > 0),
    ">=": _comparison(">=", lambda c: c >= 0),
    "+": _arithmetic("+", operator.add),
    "-": _arithmetic("-", operator.sub),
    "*": _arithmetic("*", operator.mul),
    "/": _divide,
    "||": _concat,
}

_less_equal = _BINARY["<="]
_equal = _BINARY["="]


def _in(value, items):
    results = [_equal(value, item) for item in items]
    if True in results:
        return True
    if value is None or None in items:
        return None
    return False


@lru_cache(maxsize=256)
def _like_regex(pattern: str):
    parts = [".*" if c == "%" else "." if c == "_" else re.escape(c) for c in pattern]
    return re.compile("".join(parts), re.DOTALL)


def _like(value, pattern):
    _require("string", "LIKE", value, pattern)
    if value is None or pattern is None:
        return None
    return _like_regex(pattern).fullmatch(value) is not None


def _negated(value, negated: bool):
    return _not(value) if negated else value


# Scalar functions

def _round_half_away(value, places: int) -> Decimal:
    """Round to ``places`` decimals, halves away from zero, using the
    shortest decimal that represents ``value`` (so 2.675 rounds to 2.68)."""
    if isinstance(value, float) and not math.isfinite(value):
        raise QueryError(f"cannot round {value!r}")
    d = Decimal(repr(value)) if isinstance(value, float) else Decimal(value)
    if places >= -d.as_tuple().exponent:
        return d  # already has no more than ``places`` decimals
    if places < -(d.adjusted() + 1):
        return Decimal(0)  # |value| < half a unit of the last kept place
    context = Context(prec=d.adjusted() + places + 2, rounding=ROUND_HALF_UP)
    return d.quantize(Decimal(1).scaleb(-places), context=context)


def _round(x, places=0, *, to_int=True):
    _require("number", "ROUND", x, places)
    if x is None or places is None:
        return None
    if not isinstance(places, int):
        raise QueryError(f"ROUND expects an integer number of places, got {places!r}")
    rounded = _round_half_away(x, places)
    if to_int:
        return int(rounded)
    result = float(rounded)
    if not math.isfinite(result):
        raise QueryError("numeric overflow in ROUND")
    return result


def _string_function(name: str, fn):
    def call(s):
        _require("string", name, s)
        return None if s is None else fn(s)
    return call


def _abs(x):
    _require("number", "ABS", x)
    return None if x is None else abs(x)


def _coalesce(*values):
    return next((v for v in values if v is not None), None)


# name -> (minimum arguments, maximum arguments or None, implementation)
_SCALAR_FUNCTIONS = {
    "LOWER": (1, 1, _string_function("LOWER", str.lower)),
    "UPPER": (1, 1, _string_function("UPPER", str.upper)),
    "LENGTH": (1, 1, _string_function("LENGTH", len)),
    "ABS": (1, 1, _abs),
    "ROUND": (1, 2, lambda x, *n: _round(x, *n, to_int=not n)),
    "COALESCE": (1, None, _coalesce),
}


# Aggregates: each takes the list of non-NULL argument values.

def _sum(values):
    _require("number", "SUM", *values)
    return sum(values) if values else None


def _avg(values):
    _require("number", "AVG", *values)
    return sum(values) / len(values) if values else None


def _extreme(sign: int):
    def reduce(values):
        best = None
        for value in values:
            if best is None or _compare(value, best) == sign:
                best = value
        return best
    return reduce


_AGGREGATE_FUNCTIONS = {
    "COUNT": len,
    "SUM": _sum,
    "AVG": _avg,
    "MIN": _extreme(-1),
    "MAX": _extreme(1),
}


def _is_aggregate(expr: Expr) -> bool:
    return isinstance(expr, FuncCall) and expr.name.upper() in _AGGREGATE_FUNCTIONS


# Syntax tree helpers

def _children(expr: Expr):
    for f in fields(expr):
        value = getattr(expr, f.name)
        if isinstance(value, _NODES):
            yield value
        elif isinstance(value, tuple):
            yield from value


def _contains_aggregate(expr: Expr) -> bool:
    return _is_aggregate(expr) or any(_contains_aggregate(c) for c in _children(expr))


def _expr_key(expr: Expr):
    """A structural key for expr: column and function names compare
    case-insensitively, and literals of different types never match."""
    if isinstance(expr, Literal):
        return ("Literal", type(expr.value).__name__, expr.value)
    if isinstance(expr, Column):
        return ("Column", expr.name.lower())
    parts = [type(expr).__name__]
    for f in fields(expr):
        value = getattr(expr, f.name)
        if isinstance(value, _NODES):
            value = _expr_key(value)
        elif isinstance(value, tuple):
            value = tuple(_expr_key(item) for item in value)
        elif f.name in ("name", "op"):
            value = value.upper()
        parts.append(value)
    return tuple(parts)


# Compilation

Compiled = Callable[[object], object]
# Compiles Columns and aggregates (and, when grouped, GROUP BY expressions);
# returns None for anything to be compiled structurally.
Leaf = Callable[[Expr], Optional[Compiled]]


def _compile(expr: Expr, leaf: Leaf) -> Compiled:
    compiled = leaf(expr)
    if compiled is not None:
        return compiled

    def sub(e):
        return _compile(e, leaf)

    if isinstance(expr, Literal):
        value = expr.value
        return lambda ctx: value
    if isinstance(expr, Unary):
        op = {"-": _negate, "NOT": _not}.get(expr.op.upper())
        if op is None:
            raise QueryError(f"unknown operator: {expr.op}")
        operand = sub(expr.operand)
        return lambda ctx: op(operand(ctx))
    if isinstance(expr, Binary):
        op = _BINARY.get(expr.op.upper())
        if op is None:
            raise QueryError(f"unknown operator: {expr.op}")
        left, right = sub(expr.left), sub(expr.right)
        return lambda ctx: op(left(ctx), right(ctx))
    if isinstance(expr, IsNull):
        operand, negated = sub(expr.operand), expr.negated
        return lambda ctx: (operand(ctx) is None) != negated
    if isinstance(expr, InList):
        operand, negated = sub(expr.operand), expr.negated
        items = [sub(item) for item in expr.items]
        return lambda ctx: _negated(_in(operand(ctx), [i(ctx) for i in items]), negated)
    if isinstance(expr, Between):
        operand, low, high = sub(expr.operand), sub(expr.low), sub(expr.high)
        negated = expr.negated

        def between(ctx):
            value = operand(ctx)
            result = _and(_less_equal(low(ctx), value), _less_equal(value, high(ctx)))
            return _negated(result, negated)
        return between
    if isinstance(expr, Like):
        operand, pattern, negated = sub(expr.operand), sub(expr.pattern), expr.negated
        return lambda ctx: _negated(_like(operand(ctx), pattern(ctx)), negated)
    if isinstance(expr, FuncCall):
        return _compile_scalar(expr, sub)
    raise QueryError(f"unsupported expression: {expr!r}")


def _compile_scalar(call: FuncCall, sub) -> Compiled:
    name = call.name.upper()
    if name not in _SCALAR_FUNCTIONS:
        raise QueryError(f"unknown function: {call.name}")
    if call.star:
        raise QueryError(f"{name}(*) is not allowed")
    low, high, fn = _SCALAR_FUNCTIONS[name]
    if len(call.args) < low or (high is not None and len(call.args) > high):
        expected = f"{low}" if low == high else f"{low} to {high}" if high else f"at least {low}"
        raise QueryError(f"{name} takes {expected} argument(s), got {len(call.args)}")
    args = [sub(arg) for arg in call.args]
    return lambda ctx: fn(*(arg(ctx) for arg in args))


def _compile_aggregate(call: FuncCall, row_leaf: Leaf) -> Compiled:
    name = call.name.upper()
    if call.star:
        if name != "COUNT" or call.args:
            raise QueryError(f"{name}(*) is not allowed")
        return lambda group: len(group.rows)
    if len(call.args) != 1:
        raise QueryError(f"{name} takes 1 argument, got {len(call.args)}")
    arg = _compile(call.args[0], row_leaf)
    reduce = _AGGREGATE_FUNCTIONS[name]

    def aggregate(group):
        return reduce([v for v in map(arg, group.rows) if v is not None])
    return aggregate


@dataclass
class _Group:
    key: tuple  # GROUP BY values, taken from the group's first row
    rows: List[tuple]


def _sort_key(value):
    return (0,) if value is None else (1, value)


class _Query:
    def __init__(self, select: Select, table: _Table):
        self.select = select
        self.table = table

    def row_leaf(self, aggregate_error: str) -> Leaf:
        def leaf(expr):
            if isinstance(expr, Column):
                index = self.table.column_index(expr.name)
                return lambda row: row[index]
            if _is_aggregate(expr):
                raise QueryError(aggregate_error)
            return None
        return leaf

    def group_leaf(self) -> Leaf:
        positions = {}
        for i, expr in enumerate(self.select.group_by):
            positions.setdefault(_expr_key(expr), i)
        nested = self.row_leaf("aggregate functions can't be nested")

        def leaf(expr):
            position = positions.get(_expr_key(expr))
            if position is not None:
                return lambda group: group.key[position]
            if _is_aggregate(expr):
                return _compile_aggregate(expr, nested)
            if isinstance(expr, Column):
                self.table.column_index(expr.name)  # unknown columns first
                raise QueryError(
                    f"column {expr.name} must appear in GROUP BY or be used in an aggregate"
                )
            return None
        return leaf

    def is_grouped(self) -> bool:
        s = self.select
        exprs = [item.expr for item in s.columns or ()]
        exprs += [item.expr for item in s.order_by]
        if s.having is not None:
            exprs.append(s.having)
        return bool(s.group_by) or any(_contains_aggregate(e) for e in exprs)

    def filter(self, units, condition: Optional[Expr], leaf: Leaf, clause: str):
        if condition is None:
            return units
        test = _compile(condition, leaf)
        kept = []
        for unit in units:
            value = test(unit)
            _require("boolean", clause, value)
            if value is True:
                kept.append(unit)
        return kept

    def group(self, rows):
        key_fns = [
            _compile(e, self.row_leaf("aggregate functions are not allowed in GROUP BY"))
            for e in self.select.group_by
        ]
        groups = {}
        for row in rows:
            values = tuple(fn(row) for fn in key_fns)
            key = tuple(_value_key(v) for v in values)
            if key not in groups:
                groups[key] = _Group(values, [])
            groups[key].rows.append(row)
        if not key_fns and not groups:
            return [_Group((), [])]
        return list(groups.values())

    def run(self) -> Result:
        s = self.select
        rows = self.filter(
            self.table.rows, s.where,
            self.row_leaf("aggregate functions are not allowed in WHERE"), "WHERE",
        )

        if self.is_grouped():
            if s.columns is None:
                raise QueryError("SELECT * is not allowed in a grouped query")
            leaf = self.group_leaf()
            units = self.filter(self.group(rows), s.having, leaf, "HAVING")
        else:
            if s.having is not None:
                raise QueryError("HAVING requires GROUP BY or an aggregate")
            leaf = self.row_leaf("aggregate functions are not allowed here")
            units = rows

        if s.columns is None:
            names = list(self.table.header)
            output_keys = [("*", i) for i in range(len(names))]
            outputs = [(lambda i: lambda row: row[i])(i) for i in range(len(names))]
        else:
            names = [self.output_name(item) for item in s.columns]
            output_keys = [_expr_key(item.expr) for item in s.columns]
            outputs = [_compile(item.expr, leaf) for item in s.columns]

        sort_fns = [self.sort_fn(item.expr, names, output_keys, leaf) for item in s.order_by]

        records = []
        for unit in units:
            out = tuple(fn(unit) for fn in outputs)
            records.append((out, [fn(out, unit) for fn in sort_fns]))

        for i in reversed(range(len(s.order_by))):
            kinds = {_kind(keys[i]) for _, keys in records if keys[i] is not None}
            if len(kinds) > 1:
                raise QueryError(f"cannot sort mixed types in ORDER BY item {i + 1}")
            records.sort(key=lambda r: _sort_key(r[1][i]), reverse=s.order_by[i].descending)

        result = [out for out, _ in records]
        if s.distinct:
            seen = set()
            unique = []
            for out in result:
                key = tuple(_value_key(v) for v in out)
                if key not in seen:
                    seen.add(key)
                    unique.append(out)
            result = unique

        offset = s.offset or 0
        if offset < 0 or (s.limit is not None and s.limit < 0):
            raise QueryError("LIMIT and OFFSET must not be negative")
        end = None if s.limit is None else offset + s.limit
        return Result(names, result[offset:end])

    def output_name(self, item) -> str:
        if item.alias is not None:
            return item.alias
        if isinstance(item.expr, Column):
            return self.table.header[self.table.column_index(item.expr.name)]
        return item.text

    def sort_fn(self, expr: Expr, names, output_keys, leaf: Leaf):
        """Return a function of (output row, row or group) giving a sort value."""
        if isinstance(expr, Literal) and type(expr.value) is int:
            n = expr.value
            if not 1 <= n <= len(names):
                raise QueryError(f"ORDER BY position {n} is out of range")
            return lambda out, unit: out[n - 1]
        if isinstance(expr, Column):
            matches = [i for i, name in enumerate(names) if name.lower() == expr.name.lower()]
            if len({output_keys[i] for i in matches}) > 1:
                raise QueryError(f"ORDER BY {expr.name} is ambiguous")
            if matches:
                i = matches[0]
                return lambda out, unit: out[i]
        fn = _compile(expr, leaf)
        return lambda out, unit: fn(unit)

"""Black-box tests for minisql, written against SPEC.md.

Only the public API (``minisql.run``, ``minisql.QueryError``) and the CLI
(``python -m minisql``) are used.
