        self.assertIs(self.val("'abc' LIKE 'b'"), False)
        self.assertIs(self.val("'abc' LIKE 'bc'"), False)

    def test_percent(self):
        self.assertIs(self.val("'abc' LIKE 'a%'"), True)
        self.assertIs(self.val("'abc' LIKE '%c'"), True)
        self.assertIs(self.val("'abc' LIKE '%b%'"), True)
        self.assertIs(self.val("'abc' LIKE '%x%'"), False)

    def test_percent_matches_empty(self):
        self.assertIs(self.val("'abc' LIKE 'abc%'"), True)
        self.assertIs(self.val("'' LIKE '%'"), True)

    def test_underscore(self):
        self.assertIs(self.val("'abc' LIKE 'a_c'"), True)
        self.assertIs(self.val("'abc' LIKE '___'"), True)
        self.assertIs(self.val("'abc' LIKE '__'"), False)
        self.assertIs(self.val("'ac' LIKE 'a_c'"), False)

    def test_case_sensitive(self):
        self.assertIs(self.val("'ABC' LIKE 'abc'"), False)
        self.assertIs(self.val("'abc' LIKE 'A%'"), False)

    def test_dot_is_literal(self):
        self.assertIs(self.val("'a.c' LIKE 'a.c'"), True)
        self.assertIs(self.val("'abc' LIKE 'a.c'"), False)

    def test_regex_metacharacters_are_literal(self):
        self.assertIs(self.val("'a+' LIKE 'a+'"), True)
        self.assertIs(self.val("'aa' LIKE 'a+'"), False)
        self.assertIs(self.val("'a*' LIKE 'a*'"), True)
        self.assertIs(self.val("'aaa' LIKE 'a*'"), False)
        self.assertIs(self.val("'(x)' LIKE '(x)'"), True)
        self.assertIs(self.val("'x' LIKE '(x)'"), False)
        self.assertIs(self.val("'[ab]' LIKE '[ab]'"), True)
        self.assertIs(self.val("'a' LIKE '[ab]'"), False)
        self.assertIs(self.val("'a|b' LIKE 'a|b'"), True)
        self.assertIs(self.val("'a' LIKE 'a|b'"), False)
        self.assertIs(self.val("'^a$' LIKE '^a$'"), True)
        self.assertIs(self.val("'a' LIKE '^a$'"), False)
        self.assertIs(self.val("'a?' LIKE 'a?'"), True)
        self.assertIs(self.val("'' LIKE 'a?'"), False)

    def test_backslash_is_literal(self):
        self.assertIs(self.val("'a\\b' LIKE 'a\\b'"), True)
        self.assertIs(self.val("'a\\d' LIKE 'a\\d'"), True)
        self.assertIs(self.val("'a1' LIKE 'a\\d'"), False)

    def test_not_like(self):
        self.assertIs(self.val("'abc' NOT LIKE 'a%'"), False)
        self.assertIs(self.val("'abc' NOT LIKE 'x%'"), True)

    def test_where(self):
        self.assertRowsExact(
            self.rows("SELECT name FROM people WHERE name LIKE '%e'"),
            [("Alice",), ("dave",), ("Eve",)],
        )

    def test_where_case_sensitive(self):
        self.assertEqual(
            self.rows("SELECT name FROM people WHERE name LIKE 'a%'"), []
        )


