        self.assertVal("ROUND(0.5)", 1)
        self.assertVal("ROUND(1.5)", 2)

    def test_round_negative_half_away_from_zero(self):
        self.assertVal("ROUND(-2.5)", -3)
        self.assertVal("ROUND(-0.5)", -1)
        self.assertVal("ROUND(-2.4)", -2)

    def test_round_places_is_float(self):
        v = self.val("ROUND(1.25, 1)")
        self.assertIs(type(v), float)
        self.assertAlmostEqual(v, 1.3, places=9)

    def test_round_places_negative_half(self):
        v = self.val("ROUND(-1.25, 1)")
        self.assertIs(type(v), float)
        self.assertAlmostEqual(v, -1.3, places=9)

    def test_round_places_more(self):
        v = self.val("ROUND(0.125, 2)")
        self.assertIs(type(v), float)
        self.assertAlmostEqual(v, 0.13, places=9)
        v = self.val("ROUND(1234.5678, 2)")
        self.assertAlmostEqual(v, 1234.57, places=9)

    def test_round_places_of_int_is_float(self):
        self.assertVal("ROUND(2, 1)", 2.0)

    def test_round_null_places(self):
        self.assertIsNone(self.val("ROUND(2.5, NULL)"))

    def test_coalesce(self):
        self.assertVal("COALESCE(NULL, NULL, 3)", 3)
        self.assertVal("COALESCE(1, 2)", 1)
        self.assertVal("COALESCE(NULL, 'a', 1)", "a")

    def test_coalesce_all_null(self):
        self.assertIsNone(self.val("COALESCE(NULL, NULL)"))

    def test_coalesce_single(self):
        self.assertVal("COALESCE(5)", 5)

    def test_coalesce_column(self):
        self.assertRowsExact(
            self.rows("SELECT COALESCE(bonus, 0) FROM people"),
            [(10,), (0,), (5,), (0,), (2.5,)],
        )

    def test_functions_on_columns(self):
        self.assertRowsExact(
            self.rows("SELECT UPPER(name), LENGTH(name) FROM products"),
            [("WIDGET", 6), ("GADGET", 6), ("DOOHICKEY", 9)],
        )

    def test_unknown_function(self):
        self.assertError("SELECT FOO(1) FROM one")

    def test_wrong_arity_too_many(self):
        self.assertError("SELECT LOWER('a', 'b') FROM one")
        self.assertError("SELECT ROUND(1, 2, 3) FROM one")
        self.assertError("SELECT ABS(1, 2) FROM one")

    def test_wrong_arity_too_few(self):
        self.assertError("SELECT LOWER() FROM one")
        self.assertError("SELECT UPPER() FROM one")
        self.assertError("SELECT LENGTH() FROM one")
        self.assertError("SELECT ABS() FROM one")
        self.assertError("SELECT ROUND() FROM one")


