class TestAggregates(Base):
    def agg(self, expr, where=""):
        rows = self.rows("SELECT %s FROM people %s" % (expr, where))
        self.assertEqual(len(rows), 1)
        return rows[0][0]

    def test_count_star(self):
        self.assertExact(self.agg("COUNT(*)"), 5)

    def test_count_expr_skips_null(self):
        self.assertExact(self.agg("COUNT(bonus)"), 3)
        self.assertExact(self.agg("COUNT(dept)"), 4)

    def test_count_counts_false(self):
        self.assertExact(self.agg("COUNT(bonus > 4)"), 3)

    def test_sum_ints_is_int(self):
        self.assertExact(self.agg("SUM(salary)"), 470)

    def test_sum_with_float_is_float(self):
        self.assertExact(self.agg("SUM(bonus)"), 17.5)

    def test_sum_mixed_products(self):
        rows = self.rows("SELECT SUM(price) FROM products")
        self.assertRowsExact(rows, [(44.5,)])

    def test_avg_is_float(self):
        self.assertExact(self.agg("AVG(salary)"), 94.0)

    def test_avg_ignores_null(self):
        v = self.agg("AVG(bonus)")
        self.assertIs(type(v), float)
        self.assertAlmostEqual(v, 17.5 / 3)

    def test_min_max_numbers(self):
        self.assertExact(self.agg("MIN(salary)"), 80)
        self.assertExact(self.agg("MAX(salary)"), 120)

    def test_min_max_ignore_null(self):
        self.assertExact(self.agg("MIN(bonus)"), 2.5)
        self.assertExact(self.agg("MAX(bonus)"), 10)

    def test_min_max_strings(self):
        self.assertExact(self.agg("MIN(name)"), "Alice")
        self.assertExact(self.agg("MAX(name)"), "dave")

    def test_aggregate_of_expression(self):
        self.assertExact(self.agg("SUM(salary * 2)"), 940)

    def test_expression_of_aggregates(self):
        self.assertExact(self.agg("COUNT(*) + 1"), 6)
        self.assertExact(self.agg("MAX(salary) - MIN(salary)"), 40)

    def test_aggregate_names_case_insensitive(self):
        self.assertExact(self.agg("sum(salary)"), 470)
        self.assertExact(self.agg("Count(*)"), 5)

    def test_only_nulls_give_null(self):
        where = "WHERE bonus IS NULL"
        self.assertIsNone(self.agg("SUM(bonus)", where))
        self.assertIsNone(self.agg("AVG(bonus)", where))
        self.assertIsNone(self.agg("MIN(bonus)", where))
        self.assertIsNone(self.agg("MAX(bonus)", where))
        self.assertExact(self.agg("COUNT(bonus)", where), 0)
        self.assertExact(self.agg("COUNT(*)", where), 2)

    def test_no_rows(self):
        where = "WHERE FALSE"
        self.assertExact(self.agg("COUNT(*)", where), 0)
        self.assertExact(self.agg("COUNT(salary)", where), 0)
        self.assertIsNone(self.agg("SUM(salary)", where))
        self.assertIsNone(self.agg("AVG(salary)", where))
        self.assertIsNone(self.agg("MIN(salary)", where))
        self.assertIsNone(self.agg("MAX(salary)", where))

    def test_count_star_where_false_spec_example(self):
        self.assertRowsExact(
            self.rows("SELECT COUNT(*) FROM people WHERE FALSE"), [(0,)]
        )

    def test_empty_table_single_group(self):
        self.assertRowsExact(self.rows("SELECT COUNT(*) FROM empty"), [(0,)])
        self.assertRowsExact(self.rows("SELECT SUM(a) FROM empty"), [(None,)])

    def test_nested_aggregate_error(self):
        self.assertError("SELECT SUM(COUNT(*)) FROM people")
        self.assertError("SELECT MAX(MIN(salary)) FROM people")

    def test_nested_aggregate_inside_expression_error(self):
        self.assertError("SELECT SUM(salary + MAX(salary)) FROM people")

    def test_aggregate_in_where_error(self):
        self.assertError("SELECT name FROM people WHERE COUNT(*) > 1")
        self.assertError("SELECT COUNT(*) FROM people WHERE SUM(salary) > 1")


