class TestGrouping(Base):
    def test_group_order_by_first_row(self):
        self.assertRowsExact(
            self.rows(
                "SELECT dept, COUNT(*) FROM people "
                "WHERE dept IS NOT NULL GROUP BY dept"
            ),
            [("sales", 2), ("eng", 2)],
        )

    def test_group_sum(self):
        self.assertRowsExact(
            self.rows(
                "SELECT dept, SUM(salary) FROM people "
                "WHERE dept IS NOT NULL GROUP BY dept"
            ),
            [("sales", 220), ("eng", 160)],
        )

    def test_group_without_aggregate(self):
        self.assertRowsExact(
            self.rows(
                "SELECT dept FROM people WHERE dept IS NOT NULL GROUP BY dept"
            ),
            [("sales",), ("eng",)],
        )

    def test_group_by_expression(self):
        self.assertRowsExact(
            self.rows(
                "SELECT salary > 85, COUNT(*) FROM people GROUP BY salary > 85"
            ),
            [(True, 3), (False, 2)],
        )

    def test_group_by_multiple(self):
        self.assertRowsExact(
            self.rows(
                "SELECT dept, salary, COUNT(*) FROM people "
                "WHERE dept IS NOT NULL GROUP BY dept, salary"
            ),
            [("sales", 100, 1), ("eng", 80, 2), ("sales", 120, 1)],
        )

    def test_expression_over_group_column(self):
        self.assertRowsExact(
            self.rows(
                "SELECT salary + 1, COUNT(*) FROM people GROUP BY salary"
            ),
            [(101, 1), (81, 2), (121, 1), (91, 1)],
        )

    def test_group_column_case_insensitive(self):
        self.assertRowsExact(
            self.rows(
                "SELECT DEPT, COUNT(*) FROM people "
                "WHERE dept IS NOT NULL GROUP BY dept"
            ),
            [("sales", 2), ("eng", 2)],
        )

    def test_group_by_zero_rows(self):
        self.assertEqual(
            self.rows("SELECT dept, COUNT(*) FROM people WHERE FALSE GROUP BY dept"),
            [],
        )

    def test_non_grouped_column_error(self):
        self.assertError("SELECT name, COUNT(*) FROM people GROUP BY dept")

    def test_non_grouped_column_in_expression_error(self):
        self.assertError("SELECT dept, salary + 1 FROM people GROUP BY dept")

    def test_non_grouped_column_implicit_group_error(self):
        self.assertError("SELECT name, COUNT(*) FROM people")

    def test_non_grouped_column_in_having_error(self):
        self.assertError(
            "SELECT dept FROM people GROUP BY dept HAVING name = 'bob'"
        )

    def test_non_grouped_column_with_order_by_aggregate_error(self):
        self.assertError("SELECT name FROM people ORDER BY COUNT(*)")

    def test_having_aggregate(self):
        self.assertRowsExact(
            self.rows(
                "SELECT dept FROM people GROUP BY dept HAVING COUNT(*) > 1"
            ),
            [("sales",), ("eng",)],
        )

    def test_having_sum(self):
        self.assertRowsExact(
            self.rows(
                "SELECT dept, SUM(salary) FROM people "
                "GROUP BY dept HAVING SUM(salary) > 200"
            ),
            [("sales", 220)],
        )

    def test_having_group_column(self):
        self.assertRowsExact(
            self.rows(
                "SELECT dept, COUNT(*) FROM people GROUP BY dept HAVING dept = 'eng'"
            ),
            [("eng", 2)],
        )

    def test_having_aggregate_not_in_columns(self):
        self.assertRowsExact(
            self.rows(
                "SELECT dept FROM people GROUP BY dept HAVING MAX(salary) < 100"
            ),
            [("eng",), (None,)],
        )

    def test_having_without_group_by(self):
        self.assertRowsExact(
            self.rows("SELECT COUNT(*) FROM people HAVING COUNT(*) > 1"), [(5,)]
        )
        self.assertEqual(
            self.rows("SELECT COUNT(*) FROM people HAVING COUNT(*) > 10"), []
        )

    def test_having_null_drops_group(self):
        self.assertEqual(
            self.rows("SELECT COUNT(*) FROM people HAVING NULL"), []
        )

    def test_order_by_aggregate(self):
        self.assertRowsExact(
