class TestColumns(Base):
    def test_star_file_order(self):
        r = self.run_sql("SELECT * FROM products")
        self.assertEqual(r.columns, ["id", "name", "category", "price"])
        self.assertRowsExact(
            r.rows,
            [
                (1, "widget", "tools", 25),
                (2, "gadget", "toys", 12.5),
                (3, "doohickey", "tools", 7),
            ],
        )

    def test_column_order_as_written(self):
        r = self.run_sql("SELECT price, name FROM products LIMIT 1")
        self.assertEqual(r.columns, ["price", "name"])
        self.assertRowsExact(r.rows, [(25, "widget")])

    def test_same_column_twice(self):
        self.assertRowsExact(
            self.rows("SELECT name, name FROM products LIMIT 1"),
            [("widget", "widget")],
        )

    def test_alias_with_as(self):
        self.assertEqual(
            self.columns("SELECT name AS product FROM products"), ["product"]
        )

    def test_alias_without_as(self):
        self.assertEqual(
            self.columns("SELECT price * 2 doubled FROM products"), ["doubled"]
        )

    def test_quoted_alias(self):
        self.assertEqual(
            self.columns('SELECT name AS "Product Name" FROM products'),
            ["Product Name"],
        )

    def test_alias_on_aggregate(self):
        r = self.run_sql("SELECT COUNT(*) AS n FROM products")
        self.assertEqual(r.columns, ["n"])
        self.assertRowsExact(r.rows, [(3,)])

    def test_plain_column_uses_header_spelling(self):
        self.assertEqual(
            self.columns("SELECT NAME, Price FROM products"), ["name", "price"]
        )

    def test_plain_column_header_spelling_mixed_case(self):
        self.assertEqual(self.columns("SELECT mixedcase FROM weird"), ["MixedCase"])

    def test_quoted_plain_column_uses_header_spelling(self):
        self.assertEqual(self.columns('SELECT "NAME" FROM products'), ["name"])

    def test_expression_text_count_star(self):
        self.assertEqual(self.columns("SELECT COUNT(*) FROM products"), ["COUNT(*)"])

    def test_expression_text_keeps_case(self):
        self.assertEqual(self.columns("SELECT count(*) FROM products"), ["count(*)"])

    def test_expression_text_with_spaces(self):
        self.assertEqual(
            self.columns("SELECT name, price * 2 FROM products"),
            ["name", "price * 2"],
        )

    def test_expression_text_without_spaces(self):
        self.assertEqual(self.columns("SELECT price*2 FROM products"), ["price*2"])

    def test_expression_text_column_case_as_written(self):
        self.assertEqual(self.columns("SELECT PRICE + 1 FROM products"), ["PRICE + 1"])

    def test_expression_text_function(self):
        self.assertEqual(
            self.columns("SELECT LOWER(name), SUM(price) FROM products GROUP BY name"),
            ["LOWER(name)", "SUM(price)"],
        )

    def test_expression_text_string_literal(self):
        self.assertEqual(
            self.columns("SELECT name || '!' FROM products"), ["name || '!'"]
        )

    def test_distinct(self):
        self.assertRowsExact(
            self.rows("SELECT DISTINCT category FROM products"),
            [("tools",), ("toys",)],
        )

    def test_distinct_keeps_first(self):
        self.assertRowsExact(
            self.rows("SELECT DISTINCT salary FROM people"),
            [(100,), (80,), (120,), (90,)],
        )

    def test_distinct_multiple_columns(self):
        self.assertRowsExact(
            self.rows("SELECT DISTINCT dept, salary FROM people WHERE dept IS NOT NULL"),
            [("sales", 100), ("eng", 80), ("sales", 120)],
        )

    def test_distinct_case_sensitive(self):
        self.assertRowsExact(
            self.rows("SELECT DISTINCT LOWER(name) = name FROM people"),
            [(False,), (True,)],
        )

    def test_distinct_with_order_by(self):
        self.assertRowsExact(
            self.rows("SELECT DISTINCT salary FROM people ORDER BY salary"),
            [(80,), (90,), (100,), (120,)],
        )


